      hex: la.icao24,
      callsign: la.callsign,
      originIata: lrc && lrc.origin && lrc.origin.iata !== airportIata ? lrc.origin.iata : null,
      aircraftType: la.aircraftType,
      lat: la.lat,
      lng: la.lng,
      altFt: 0,
      distKm: justLanded[jl].distKm,
      etaMin: 0,
      arrivalScore: 0,
      proximity: false,
      taxiingIn: true,
      parked: lSpd < 3,
